const source = $('Execute Workflow Trigger').item.json || {};
const payload = source.payload || {};
const message = source.message || payload.message || payload.body?.message || {};
const chatId = source.chatId || message.chat?.id || payload.chatId || '';
const raw = String(source.rawText || message.text || payload.text || '').trim();

// Lay tu khoa tim kiem tu cau lenh
const query = raw
  .replace(/^(doc mail|đọc mail|noi dung mail|nội dung mail|read mail|read email|open mail|open email)\s*/i, '')
  .replace(/\s+/g, ' ')
  .trim();

const hasQuery = Boolean(query);
const guidance = '📧 <b>Đọc email</b>\n\nBạn hãy nhập theo mẫu:\n- đọc mail từ Google\n- nội dung mail về đơn hàng\n- read mail from boss';

return [{ json: { ...source, payload, message, chatId, query, hasQuery, response: hasQuery ? '' : guidance } }];

const source = $('Chuan Bi Doc Email').item.json;
const rows = $input.all().map(item => item.json || {}).filter(e => e && Object.keys(e).length > 0 && (e.id || e.subject));

if (rows.length === 0) {
  return [{ json: { chatId: source.chatId, text: '⚠️ Không tìm thấy email phù hợp với: ' + source.query } }];
}

const email = rows[0];
const from = email.from?.value?.[0]?.name || email.from?.value?.[0]?.address || email.from || 'Không rõ';
const to = email.to?.value?.[0]?.address || email.to || '';
const subject = email.subject || 'Không có tiêu đề';
const date = email.date ? new Date(email.date).toLocaleString('vi-VN', { timeZone: 'Asia/Ho_Chi_Minh' }) : '';

// Lay noi dung text, gioi han 1500 ky tu
let body = email.textPlain || email.text || email.snippet || '';
if (body.length > 1500) body = body.substring(0, 1500) + '\n\n<i>... (nội dung đã được cắt bớt)</i>';

let text = '📧 <b>Chi tiết email</b>\n\n';
text += `📝 <b>${subject}</b>\n`;
text += `👤 Từ: ${from}\n`;
if (to) text += `📨 Đến: ${to}\n`;
text += `🕒 ${date}\n\n`;
text += `${body}`;

return [{ json: { chatId: source.chatId, text: text.trim() } }];
